import { FileHelper, z } from '@start9labs/start-sdk'
import { sdk } from '../sdk'

// route96's own config file (upstream format: see config.yaml in v0l/route96).
// Fully regenerated by main.ts on every start; never hand-edit it.
// Only keys this package manages are listed; heavy optional features
// (label_models / AI labelling, payments, retention) are deliberately absent.
const shape = z.looseObject({
  listen: z.string(),
  database: z.string(),
  storage_dir: z.string(),
  max_upload_bytes: z.number(),
  public_url: z.string(),
  whitelist: z.array(z.string()),
})

export const configYaml = FileHelper.yaml(
  { base: sdk.volumes.startos, subpath: '/config.yaml' },
  shape,
)
